frappe.ui.form.on('HeroSlider', {
    start_date: function(frm) {
        frm.trigger('validate_dates');
    },

    end_date: function(frm) {
        frm.trigger('validate_dates');
    },

    validate_dates: function(frm) {
        if (frm.doc.start_date && frm.doc.end_date) {
            let start_date = moment(frm.doc.start_date);
            let end_date = moment(frm.doc.end_date);

            if (end_date.isBefore(start_date)) {
                frappe.msgprint(__('End Date cannot be before Start Date'));
                frm.set_value('end_date', '');
            }
        }
    }
});

frappe.ui.form.on('Banner Section', {
    refresh(frm) {
        frm.trigger('is_active');
    },
    start_date(frm) {
        frm.trigger('is_active');
    },
    end_date(frm) {
        frm.trigger('is_active');
    },
    is_active(frm) {
        const now = moment();
        let active = 1;

        // Check start datetime
        if (frm.doc.start_date) {
            const startMoment = moment(frm.doc.start_date, "YYYY-MM-DD HH:mm:ss");
            if (startMoment.isValid() && now.isBefore(startMoment)) {
                active = 0;
            }
        }

        // Check end datetime ONLY if provided and valid
        if (frm.doc.end_date) {
            const endMoment = moment(frm.doc.end_date, "YYYY-MM-DD HH:mm:ss");
            if (endMoment.isValid() && now.isSameOrAfter(endMoment)) {
                active = 0;
            }
        }

        if (frm.doc.is_active !== active) {
            frm.set_value('is_active', active);
        }
    }
});

