frappe.ui.form.on("Item", {
    refresh(frm) {
        render_kunyo_specifications(frm);
    },

    item_group(frm) {
        const old_category = frm.doc.custom_specification_category;
        const new_category = get_spec_category(frm);

        if (old_category && new_category && old_category !== new_category) {
            frm.set_value("custom_specification_data", "");
            frm.set_value("custom_saved_specifications", "");
        }

        render_kunyo_specifications(frm);
    }
});

function render_kunyo_specifications(frm) {
    const html_field = "custom_item_specifications";
    const json_field = "custom_specification_data";
    const html_save_field = "custom_saved_specifications";
    const category_field = "custom_specification_category";

    if (!frm.fields_dict[html_field]) {
        console.warn("Missing custom field:", html_field);
        return;
    }

    const category = get_spec_category(frm);
    const schema = KUNYO_SPEC_SCHEMAS[category];

    if (!category || !schema) {
        frm.fields_dict[html_field].$wrapper.html(`
            <div style="padding:12px;border:1px solid #d8d8d8;border-radius:6px;background:#fff;">
                <b>No specification fields found.</b><br>
                Please select a valid Item Group.
            </div>
        `);
        return;
    }

    const saved_data = safe_json_parse(frm.doc[json_field]);
    const has_saved_specs = has_meaningful_saved_specs(saved_data);

    let html = `
        <div class="kunyo-spec-wrapper">
            <style>
                .kunyo-spec-wrapper {
                    border: 1px solid #d1d8dd;
                    border-radius: 6px;
                    background: #fff;
                    padding: 14px;
                    margin-top: 8px;
                }
                .kunyo-spec-header {
                    margin-bottom: 12px;
                    padding-bottom: 10px;
                    border-bottom: 1px solid #e5e7eb;
                }
                .kunyo-spec-title {
                    font-size: 16px;
                    font-weight: 600;
                    margin: 0;
                    color: #1f2937;
                }
                .kunyo-spec-note {
                    margin: 4px 0 0;
                    color: #6b7280;
                    font-size: 12px;
                }
                .kunyo-spec-section {
                    border: 1px solid #e5e7eb;
                    border-radius: 6px;
                    margin-top: 12px;
                    background: #fafafa;
                }
                .kunyo-spec-section-title {
                    font-size: 14px;
                    font-weight: 600;
                    padding: 10px 12px;
                    border-bottom: 1px solid #e5e7eb;
                    background: #f5f7fa;
                    color: #111827;
                }
                .kunyo-spec-grid {
                    display: grid;
                    grid-template-columns: repeat(2, minmax(260px, 1fr));
                    gap: 12px;
                    padding: 12px;
                }
                .kunyo-spec-field label {
                    display: block;
                    font-size: 12px;
                    font-weight: 600;
                    color: #374151;
                    margin-bottom: 4px;
                }
                .kunyo-spec-input {
                    background: #fff !important;
                    border: 1px solid #d1d5db !important;
                    border-radius: 4px !important;
                    height: 34px !important;
                    font-size: 13px !important;
                }
                .kunyo-spec-input:focus {
                    border-color: #2490ef !important;
                    box-shadow: 0 0 0 1px #2490ef33 !important;
                }
                .kunyo-spec-actions {
                    margin-top: 14px;
                    display: flex;
                    gap: 8px;
                    align-items: center;
                    flex-wrap: wrap;
                }
                .kunyo-spec-preview {
                    margin-top: 14px;
                    border: 1px solid #e5e7eb;
                    border-radius: 6px;
                    background: #fff;
                    padding: 12px;
                }
                .kunyo-spec-preview h5 {
                    margin-top: 0;
                    margin-bottom: 8px;
                    font-size: 14px;
                    font-weight: 600;
                }
                .kunyo-spec-preview h6 {
                    margin-top: 12px;
                    margin-bottom: 6px;
                    font-size: 13px;
                    font-weight: 600;
                }
                .kunyo-spec-preview p {
                    margin: 0 0 4px;
                    font-size: 12px;
                }
                @media (max-width: 900px) {
                    .kunyo-spec-grid {
                        grid-template-columns: 1fr;
                    }
                }
            </style>

            <div id="kunyo_spec_form_area" style="${has_saved_specs ? "display:none;" : ""}">
                <div class="kunyo-spec-header">
                    <h4 class="kunyo-spec-title">${escape_html(category)} Specifications</h4>
                    <p class="kunyo-spec-note">Please fill the specifications form below.</p>
                </div>
    `;

    schema.sections.forEach(section => {
        html += `
            <div class="kunyo-spec-section">
                <div class="kunyo-spec-section-title">${escape_html(section.section)}</div>
                <div class="kunyo-spec-grid">
        `;

        section.fields.forEach(field => {
            const key = make_spec_key(section.section, field.label);
            const value = get_saved_value(saved_data, section.section, field.label, key);
            const placeholder = get_placeholder(field.label);

            html += `
                <div class="kunyo-spec-field">
                    <label>${escape_html(field.label)}</label>
                    <input
                        type="text"
                        class="form-control kunyo-spec-input"
                        data-section="${escape_attr(section.section)}"
                        data-label="${escape_attr(field.label)}"
                        data-icon="${escape_attr(field.icon || "")}"
                        data-key="${escape_attr(key)}"
                        value="${escape_attr(value)}"
                        placeholder="${escape_attr(placeholder)}"
                    >
                </div>
            `;
        });

        html += `
                </div>
            </div>
        `;
    });

    html += `
                <div class="kunyo-spec-actions">
                    <button type="button" class="btn btn-primary btn-sm" id="kunyo_save_specs_btn">
                        Save Specifications
                    </button>

                    <button type="button" class="btn btn-default btn-sm" id="kunyo_clear_form_btn">
                        Clear Fields
                    </button>
                </div>
            </div>

            <div id="kunyo_saved_preview"></div>
        </div>
    `;

    frm.fields_dict[html_field].$wrapper.html(html);

    bind_kunyo_spec_events(frm, html_field, category, json_field, html_save_field, category_field);

    if (has_saved_specs) {
        show_saved_preview(frm, saved_data);
    } else {
        wrapper_clear_preview(frm);
    }
}

function bind_kunyo_spec_events(frm, html_field, category, json_field, html_save_field, category_field) {
    const wrapper = frm.fields_dict[html_field].$wrapper;

    wrapper.find(".kunyo-spec-input")
        .off("input")
        .on("input", function () {
            sync_related_spec_value(wrapper, $(this));
        });

    wrapper.find("#kunyo_save_specs_btn")
        .off("click")
        .on("click", function () {
            const final_data = collect_specification_data(frm, html_field, category);

            if (!has_meaningful_saved_specs(final_data)) {
                frappe.show_alert({
                    message: "Please fill at least one specification before saving.",
                    indicator: "orange"
                });
                return;
            }

            const preview_html = build_saved_preview_html(final_data);

            frm.set_value(json_field, JSON.stringify(final_data, null, 2));
            frm.set_value(html_save_field, preview_html);

            if (frm.fields_dict[category_field]) {
                frm.set_value(category_field, category);
            }

            show_saved_preview(frm, final_data);
            wrapper.find("#kunyo_spec_form_area").hide();

            frappe.show_alert({
                message: "Specifications saved successfully.",
                indicator: "green"
            });
        });

    wrapper.find("#kunyo_clear_form_btn")
        .off("click")
        .on("click", function () {
            wrapper.find(".kunyo-spec-input").val("");
        });

    wrapper.off("click", "#kunyo_edit_specs_btn")
        .on("click", "#kunyo_edit_specs_btn", function () {
            wrapper.find("#kunyo_spec_form_area").show();
            wrapper.find("#kunyo_saved_preview").hide();

            frappe.show_alert({
                message: "Edit mode enabled.",
                indicator: "orange"
            });
        });

    wrapper.off("click", "#kunyo_clear_specs_btn")
        .on("click", "#kunyo_clear_specs_btn", function () {
            frappe.confirm("Clear all specification fields?", function () {
                wrapper.find(".kunyo-spec-input").val("");

                frm.set_value(json_field, "");
                frm.set_value(html_save_field, "");

                if (frm.fields_dict[category_field]) {
                    frm.set_value(category_field, category);
                }

                wrapper.find("#kunyo_saved_preview").html("").hide();
                wrapper.find("#kunyo_spec_form_area").show();

                frappe.show_alert({
                    message: "Specification fields cleared.",
                    indicator: "orange"
                });
            });
        });
}

function has_meaningful_saved_specs(data) {
    if (!data || Object.keys(data).length === 0) return false;

    if (data.raw_specs && Object.keys(data.raw_specs).length > 0) return true;

    if (data.highlight_specs && data.highlight_specs.length > 0) return true;

    if (
        data.full_specs &&
        data.full_specs["Full Specs"] &&
        data.full_specs["Full Specs"].length > 0
    ) {
        return true;
    }

    if (
        data.recommended_extra_fields &&
        Object.keys(data.recommended_extra_fields).length > 0
    ) {
        return true;
    }

    return false;
}

function wrapper_clear_preview(frm) {
    const wrapper = frm.fields_dict["custom_item_specifications"].$wrapper;
    wrapper.find("#kunyo_saved_preview").html("").hide();
}

function sync_related_spec_value(wrapper, current_input) {
    const source_label = current_input.attr("data-label");
    const value = current_input.val() || "";
    const source_key = normalize_label_for_sync(source_label);

    if (!source_key) return;

    wrapper.find(".kunyo-spec-input").each(function () {
        const target = $(this);

        if (target[0] === current_input[0]) return;

        const target_label = target.attr("data-label");
        const target_key = normalize_label_for_sync(target_label);

        if (!target_key) return;
        if (source_key !== target_key) return;

        target.val(value);
    });
}

