function collect_specification_data(frm, html_field, category) {
    let highlight_specs = [];
    let full_specs = {};
    let recommended_extra_fields = {};
    let raw_specs = {};

    frm.fields_dict[html_field].$wrapper.find(".kunyo-spec-input").each(function () {
        const section = $(this).attr("data-section");
        const label = $(this).attr("data-label");
        const icon = $(this).attr("data-icon");
        const key = $(this).attr("data-key");
        const value = ($(this).val() || "").trim();

        if (!value) return;

        raw_specs[key] = value;

        if (section === "Highlight Specs") {
            highlight_specs.push({
                icon: icon,
                label: label,
                value: value
            });
        } else if (section === "Additional Product Details") {
            recommended_extra_fields[to_schema_key(label)] = normalize_extra_value(label, value);
        } else if (section === "Full Specs") {
            if (!full_specs["Full Specs"]) {
                full_specs["Full Specs"] = [];
            }

            full_specs["Full Specs"].push({
                label: label,
                value: value
            });
        }
    });

    return {
        category: category,
        highlight_specs: highlight_specs,
        full_specs: full_specs,
        recommended_extra_fields: recommended_extra_fields,
        raw_specs: raw_specs
    };
}

function get_spec_category(frm) {
    const group = (frm.doc.item_group || "").trim();
    return KUNYO_CATEGORY_ALIASES[group] || group;
}

