function simple_fields(labels) {
    return labels.map(label => ({ label: label, icon: "" }));
}

function icon_fields(labels, icons) {
    return labels.map((label, index) => ({
        label: label,
        icon: icons[index] || ""
    }));
}

function make_spec_key(section, label) {
    return section + " - " + label;
}

function get_saved_value(saved_data, section, label, key) {
    if (!saved_data) return "";

    if (saved_data.raw_specs && saved_data.raw_specs[key]) return saved_data.raw_specs[key];

    if (section === "Highlight Specs" && Array.isArray(saved_data.highlight_specs)) {
        const row = saved_data.highlight_specs.find(item => item.label === label);
        return row ? row.value || "" : "";
    }

    if (section === "Full Specs" && saved_data.full_specs) {
        const rows = saved_data.full_specs["Full Specs"] || [];
        const row = rows.find(item => item.label === label);
        return row ? row.value || "" : "";
    }

    if (section === "Additional Product Details") {
        const extra = saved_data.recommended_extra_fields || {};
        const schema_key = to_schema_key(label);
        const val = extra[schema_key];

        if (Array.isArray(val)) return val.join(", ");
        if (typeof val === "boolean") return val ? "Yes" : "No";
        if (val && typeof val === "object") return JSON.stringify(val);

        return val || "";
    }

    return "";
}

function show_saved_preview(frm, data) {
    const wrapper = frm.fields_dict["custom_item_specifications"].$wrapper;
    const preview_html = build_saved_preview_html(data);

    if (preview_html) {
        wrapper.find("#kunyo_saved_preview").html(preview_html).show();
    } else {
        wrapper.find("#kunyo_saved_preview").html("").hide();
    }
}

function build_saved_preview_html(data) {
    if (!has_meaningful_saved_specs(data)) return "";

    let html = `<div class="kunyo-spec-preview"><h5>Saved Specification Preview</h5>`;

    if (data.highlight_specs && data.highlight_specs.length) {
        html += `<h6>Highlight Specs</h6>`;
        data.highlight_specs.forEach(row => {
            html += `<p><strong>${escape_html(row.label)}:</strong> ${escape_html(row.value)} <span style="color:#6b7280;">(${escape_html(row.icon)})</span></p>`;
        });
    }

    if (data.full_specs && data.full_specs["Full Specs"]) {
        html += `<h6>Full Specs</h6>`;
        data.full_specs["Full Specs"].forEach(row => {
            html += `<p><strong>${escape_html(row.label)}:</strong> ${escape_html(row.value)}</p>`;
        });
    }

    const extra = data.recommended_extra_fields;
    if (extra && Object.keys(extra).length) {
        html += `<h6>Additional Product Details</h6>`;
        Object.keys(extra).forEach(key => {
            let value = extra[key];
            if (Array.isArray(value)) value = value.join(", ");
            if (typeof value === "boolean") value = value ? "Yes" : "No";
            if (value && typeof value === "object") value = JSON.stringify(value);
            html += `<p><strong>${escape_html(key)}:</strong> ${escape_html(value)}</p>`;
        });
    }

    html += `
        <div class="kunyo-spec-actions">
            <button type="button" class="btn btn-warning btn-sm" id="kunyo_edit_specs_btn">
                Edit Specifications
            </button>

            <button type="button" class="btn btn-default btn-sm" id="kunyo_clear_specs_btn">
                Clear Fields
            </button>
        </div>
    `;

    html += `</div>`;
    return html;
}

function to_schema_key(label) {
    const map = {
        "Variants": "variants",
        "Short Description": "short_description",
        "Key Selling Points": "key_selling_points",
        "Use Case Badges": "use_case_badges",
        "In Box Contents": "in_box_contents",
        "Warranty": "warranty",
        "Certifications": "certifications",
        "Compare Enabled": "compare_enabled",
        "Tags": "tags"
    };

    return map[label] || frappe.scrub(label);
}

function normalize_extra_value(label, value) {
    if (label === "Compare Enabled") {
        return ["yes", "true", "1", "enabled"].includes(value.toLowerCase());
    }

    if (["Certifications", "Tags", "In Box Contents", "Use Case Badges", "Key Selling Points"].includes(label)) {
        return value.split(",").map(v => v.trim()).filter(Boolean);
    }

    return value;
}

