function safe_json_parse(value) {
    if (!value) return {};

    try {
        return JSON.parse(value);
    } catch (e) {
        console.warn("Invalid Kunyo specification JSON:", e);
        return {};
    }
}

function escape_html(value) {
    return String(value || "")
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#039;");
}

function escape_attr(value) {
    return escape_html(value);
}

