function generate_variants(frm) {

    let rows = frm.doc.custom_variant_attributes || [];

    if (!rows.length) {
        frappe.msgprint("Please add Variant Attributes first.");
        return;
    }

    let grouped = {};

    rows.forEach(row => {

        if (!row.attribute || !row.attribute_value) {
            return;
        }

        if (!grouped[row.attribute]) {
            grouped[row.attribute] = [];
        }

        grouped[row.attribute].push(row.attribute_value);

    });

    let values = Object.values(grouped);

    if (!values.length) {
        frappe.msgprint("No Variant Values found.");
        return;
    }

    let combinations = cartesian(values);

    frm.clear_table("custom_generated_variants");

    combinations.forEach(combo => {

        let child = frm.add_child("custom_generated_variants");

        child.variant_key = combo.join(" | ");
        child.sku = "";
        child.price = 0;

    });

    frm.refresh_field("custom_generated_variants");

    frappe.show_alert({
        message: __("Variants Generated"),
        indicator: "green"
    });

}


function cartesian(arr) {

    return arr.reduce(function(a, b) {

        let ret = [];

        a.forEach(function(x) {

            b.forEach(function(y) {

                ret.push(x.concat([y]));

            });

        });

        return ret;

    }, [[]]);

}

