function bind_kunyo_variant_events(frm, wrapper) {
    wrapper.off("click", "#kunyo_edit_variants").on("click", "#kunyo_edit_variants", function () {
        let scroll_pos = window.scrollY;

        wrapper.find("#kunyo_attribute_area").show();
        wrapper.find("#kunyo_generated_variants").html("");
        wrapper.find("#kunyo_edit_area").hide();

        setTimeout(() => window.scrollTo(0, scroll_pos), 0);
    });

    wrapper.off("click", "#kunyo_add_attribute").on("click", "#kunyo_add_attribute", function () {
        wrapper.find("#kunyo_variant_attributes").append(
            kunyo_attribute_block_html({
                attribute: "",
                values: [{ value: "", price: 0 }]
            })
        );
    });

    wrapper.off("click", ".kunyo_add_value").on("click", ".kunyo_add_value", function () {
        let block = $(this).closest(".kunyo-attribute-block");
        block.find(".kunyo-value-list").append(
            kunyo_value_row_html({ value: "", price: 0 }, block.find(".kunyo_variant_attribute").val())
        );
    });

    wrapper.off("click", ".kunyo_remove_value").on("click", ".kunyo_remove_value", function () {
        let block = $(this).closest(".kunyo-attribute-block");

        if (block.find(".kunyo-value-row").length <= 1) {
            frappe.show_alert({
                message: "At least one value is required.",
                indicator: "orange"
            });
            return;
        }

        $(this).closest(".kunyo-value-row").remove();
        wrapper.find("#kunyo_generated_variants").html("");
    });

    wrapper.off("click", ".kunyo_remove_attribute").on("click", ".kunyo_remove_attribute", function () {
        $(this).closest(".kunyo-attribute-block").remove();
        wrapper.find("#kunyo_generated_variants").html("");
    });

    wrapper.off("click", "#kunyo_generate_variants").on("click", "#kunyo_generate_variants", function () {
        let scroll_pos = window.scrollY;

        let attributes = collect_kunyo_attributes_from_ui(wrapper);

        if (!attributes.length) {
            frappe.show_alert({
                message: "Please add at least one valid attribute value.",
                indicator: "orange"
            });
            return;
        }

        let variants = generate_kunyo_variant_combinations(attributes);

        if (!variants.length) {
            frappe.show_alert({
                message: "No valid variants found.",
                indicator: "orange"
            });
            return;
        }

        render_kunyo_generated_variants(wrapper, variants);

        wrapper.find("#kunyo_attribute_area").hide();
        wrapper.find("#kunyo_edit_area").show();

        save_kunyo_product_variants(frm);

        setTimeout(() => window.scrollTo(0, scroll_pos), 0);

        frappe.show_alert({
            message: variants.length + " variants generated.",
            indicator: "green"
        });
    });

    wrapper.off("input", ".kunyo_generated_price_input").on("input", ".kunyo_generated_price_input", function () {
        save_kunyo_product_variants(frm);
    });
}

