function collect_kunyo_attributes_from_ui(wrapper) {
    let attributes = [];

    wrapper.find(".kunyo-attribute-block").each(function () {
        let block = $(this);
        let attribute = (block.find(".kunyo_variant_attribute").val() || "").trim();

        if (!attribute) return;

        let values = [];

        block.find(".kunyo-value-row").each(function () {
            let row = $(this);
            let value = (row.find(".kunyo_variant_value").val() || "").trim();
            let price = flt(row.find(".kunyo_variant_price").val() || 0);

            if (value && !values.some(v => v.value.toLowerCase() === value.toLowerCase())) {
                values.push({
                    value: value,
                    price: price
                });
            }
        });

        if (values.length) {
            attributes.push({
                attribute: attribute,
                values: values
            });
        }
    });

    return attributes;
}

function generate_kunyo_variant_combinations(attributes) {
    let valid_attributes = attributes.filter(row => row.values && row.values.length);
    let variants = [];

    function generate(index, current) {
        if (index === valid_attributes.length) {
            let first_price = 0;

            current.forEach(row => {
                if (!first_price && flt(row.price || 0) > 0) {
                    first_price = flt(row.price || 0);
                }
            });

            variants.push({
                values: current.map(row => ({
                    attribute: row.attribute,
                    value: row.value
                })),
                variant_price: first_price
            });

            return;
        }

        valid_attributes[index].values.forEach(item => {
            if (!item.value) return;

            generate(index + 1, current.concat([{
                attribute: valid_attributes[index].attribute,
                value: item.value,
                price: flt(item.price || 0)
            }]));
        });
    }

    generate(0, []);
    return variants;
}

function render_kunyo_generated_variants(wrapper, variants) {
    let html = `
        <div class="kunyo-generated-box">
            <div class="kunyo-generated-title">
                Generated Variants (${variants.length})
            </div>
    `;

    variants.forEach((variant, index) => {
        let rows = Array.isArray(variant.values) ? variant.values : [];
        let price = flt(variant.variant_price || 0);

        html += `
            <div class="kunyo-generated-card" data-variant-index="${index}">
                <div style="font-weight:600; margin-bottom:10px;">
                    Variant ${index + 1}
                </div>
        `;

        rows.forEach(row => {
            html += `
                <div class="kunyo-generated-line">
                    <strong>${kunyo_escape(row.attribute)}:</strong>
                    ${kunyo_escape(row.value)}
                </div>
            `;
        });

        html += `
                <div class="kunyo-generated-price">
                    <label class="kunyo-field-label">Variant Price</label>
                    <input type="number"
                        class="form-control kunyo_generated_price_input"
                        value="${kunyo_escape(price)}">
                </div>
            </div>
        `;
    });

    html += `</div>`;

    wrapper.find("#kunyo_generated_variants").html(html);
}

function collect_generated_variants_from_ui(wrapper) {
    let variants = [];

    wrapper.find(".kunyo-generated-card").each(function () {
        let card = $(this);
        let rows = [];

        card.find(".kunyo-generated-line").each(function () {
            let text = $(this).text().trim();
            let parts = text.split(":");

            if (parts.length >= 2) {
                rows.push({
                    attribute: parts[0].trim(),
                    value: parts.slice(1).join(":").trim()
                });
            }
        });

        variants.push({
            values: rows,
            variant_price: flt(card.find(".kunyo_generated_price_input").val() || 0)
        });
    });

    return variants;
}

function save_kunyo_product_variants(frm) {
    const html_field = "custom__product_variant_details";
    const data_field = "custom_product_variant_data";

    if (!frm.fields_dict[html_field]) return;

    if (!is_kunyo_variant_enabled(frm)) {
        frm.doc[data_field] = "";
        return;
    }

    const wrapper = frm.fields_dict[html_field].$wrapper;

    let attributes = collect_kunyo_attributes_from_ui(wrapper);
    let generated_variants = [];

    if (wrapper.find(".kunyo-generated-card").length) {
        generated_variants = collect_generated_variants_from_ui(wrapper);
    } else {
        generated_variants = generate_kunyo_variant_combinations(attributes);
    }

    frm.doc[data_field] = JSON.stringify({
        attributes: attributes,
        generated_variants: generated_variants
    }, null, 2);
}

function normalize_kunyo_variant_data(data) {
    if (data && data.attributes && Array.isArray(data.attributes)) {
        return data.attributes.map(row => ({
            attribute: row.attribute || "",
            values: Array.isArray(row.values)
                ? row.values.map(value => ({
                    value: typeof value === "object" ? value.value || "" : value || "",
                    price: typeof value === "object" ? flt(value.price || 0) : 0
                }))
                : [{ value: "", price: 0 }]
        }));
    }

    return [];
}

function get_kunyo_value_placeholder(attribute_name) {
    let attr = String(attribute_name || "").trim().toLowerCase();

    const placeholders = {
        "colour": "Example: Black, Grey, Silver",
        "color": "Example: Black, Grey, Silver",
        "ram": "Example: 8GB, 16GB, 32GB",
        "storage": "Example: 512GB SSD, 1TB SSD",
        "size": "Example: Small, Medium, Large, XL",
        "brand": "Example: Asus, Dell, HP, Lenovo"
    };

    return placeholders[attr] || "Example: Enter value";
}

function kunyo_escape(value) {
    return String(value || "")
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#039;");
}

frappe.ui.form.on('Item', {
    refresh(frm) {
        set_delivery_fields(frm);
    },

    custom_delivery_option(frm) {
        set_delivery_fields(frm);
    }
});

function set_delivery_fields(frm) {
    let option = frm.doc.custom_delivery_option || "";

    let show_cod = option === "COD" || option === "COD and Pickup From Store";
    let show_pickup = option === "Pickup From Store" || option === "COD and Pickup From Store";

    frm.set_df_property("custom_cod_details", "hidden", !show_cod);
    frm.set_df_property("custom_cod_charge", "hidden", !show_cod);
    frm.set_df_property("custom_cod_available_areas", "hidden", !show_cod);
    frm.set_df_property("custom_cod_instructions", "hidden", !show_cod);

    frm.set_df_property("custom_pickup_details", "hidden", !show_pickup);
    frm.set_df_property("custom_pickup_location", "hidden", !show_pickup);
    frm.set_df_property("custom_pickup_ready_time", "hidden", !show_pickup);
    frm.set_df_property("custom_pickup_instructions", "hidden", !show_pickup);

    frm.refresh_fields();
}
